using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class NightPolishAudit{static NightPolishAudit(){EditorApplication.update+=Run;}static void Run(){if(EditorApplication.isCompiling||!File.Exists("NightPolishAudit.request"))return;File.Delete("NightPolishAudit.request");var sc=SceneManager.GetActiveScene();var c=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();var log=new System.Text.StringBuilder("PRESET="+AssetDatabase.GetAssetPath(c.presets)+" transition="+c.transitionSeconds+"\n");foreach(var r in sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true))){var f=r.GetComponent<MeshFilter>();if(!f||!f.sharedMesh||r.bounds.size.y<12||r.bounds.size.x<6||r.bounds.size.z<6)continue;var path=AssetDatabase.GetAssetPath(f.sharedMesh);if(!path.EndsWith(".fbx",StringComparison.OrdinalIgnoreCase))continue;log.AppendLine(r.name+" | "+r.bounds+" | "+string.Join(",",r.sharedMaterials.Select(m=>m?m.name+" : "+m.shader.name:"null"))+" | "+path);}File.WriteAllText("FinalEnvironmentRoadReview/NightPolishAudit.txt",log.ToString());}}
